def partition(cmd, varargs, target_concurrency, _max_length):
    import math
    from itertools import chain

    if not varargs:
        return [cmd]

    varargs = list(chain.from_iterable(
        (arg if isinstance(arg, (list, tuple)) else [arg])
        for arg in varargs
    ))

    if not varargs:
        return [cmd]

    def _partition_helper(args):
        if not args:
            return []

        ret = []
        current = list(cmd)
        for arg in args:
            test_cmd = current + [arg]
            if len(' '.join(test_cmd)) <= _max_length:
                current.append(arg)
            else:
                ret.append(current)
                current = list(cmd) + [arg]
        ret.append(current)
        return ret

    partitions = _partition_helper(varargs)

    if len(partitions) <= target_concurrency:
        return partitions

    chunks = min(len(partitions), target_concurrency)
    avg = len(partitions) / chunks
    return [
        partitions[int(i * avg):int((i + 1) * avg)]
        for i in range(chunks)
    ]

