def _legacy_mergeOrderings(orderings):
    """
    Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']
    """
    # Check suffix consistency
    seen = {}
    for ordering in orderings:
        for i, elem in enumerate(ordering):
            if elem in seen:
                if ordering[i:] != seen[elem]:
                    raise ValueError(f"Inconsistent suffix for element {elem!r}")
            else:
                seen[elem] = ordering[i:]

    # Build dependency graph
    all_elements = []
    for ordering in orderings:
        for elem in ordering:
            if elem not in all_elements:
                all_elements.append(elem)

    in_degree = {elem: 0 for elem in all_elements}
    graph = {elem: [] for elem in all_elements}

    for ordering in orderings:
        for i in range(len(ordering) - 1):
            a, b = ordering[i], ordering[i + 1]
            if b not in graph[a]:
                graph[a].append(b)
                in_degree[b] += 1

    # Topological sort with deterministic ordering
    result = []
    queue = [elem for elem in all_elements if in_degree[elem] == 0]
    queue.sort(key=lambda x: all_elements.index(x))

    while queue:
        elem = queue.pop(0)
        result.append(elem)
        neighbors = sorted(graph[elem], key=lambda x: all_elements.index(x))
        for neighbor in neighbors:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)
                queue.sort(key=lambda x: all_elements.index(x))

    return result

