def to_csv(self, separator=",", header=None):
    """Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    import io
    output = io.StringIO()

    if header is not None:
        output.write(header + "\n")

    for point in self:
        # Handle point structure dynamically
        if hasattr(point, "coordinate") and hasattr(point, "value"):
            coords = point.coordinate
            value = point.value
        elif isinstance(point, (list, tuple)) and len(point) >= 2:
            coords = point[0]
            value = point[1]
        else:
            # Fallback: treat entire point as value with empty coordinate
            coords = []
            value = point

        # Ensure coords is iterable
        if not hasattr(coords, "__iter__") or isinstance(coords, str):
            coords = [coords]

        # Flatten value if it's iterable (but not string)
        if hasattr(value, "__iter__") and not isinstance(value, str):
            try:
                value_parts = list(value)
            except:
                value_parts = [value]
        else:
            value_parts = [value]

        # Build row
        row_parts = []
        for coord in coords:
            row_parts.append(str(coord))
        for val_part in value_parts:
            row_parts.append(str(val_part))

        output.write(separator.join(row_parts) + "\n")

    return output.getvalue()

