def get_logical_path_map(inventory, version):
    state = inventory['versions'][version]['state']
    manifest = inventory['manifest']
    file_map = {}
    for logical_path, digests in state.items():
        for digest in digests:
            if digest in manifest:
                if logical_path not in file_map:
                    file_map[logical_path] = set()
                file_map[logical_path].add(manifest[digest])
    return file_map

