def _eval_file(prefix, file_path):
    if file_path.endswith(".xml"):
        # ignore XML files
        return

    filename = os.path.basename(file_path)
    fname, ext = os.path.splitext(filename)
    suffix = fname.replace(prefix, "")
    lang = suffix[1:]

    if lang:
        return dict(
            component_id=lang,
            file_path=file_path,
        )
    else:
        return dict(
            component_id=filename,
            component_name=fname,
            ftype=ext[1:],
            file_path=file_path,
        )

