def absorb(args):
    def apply_absorption(expr):
        if isinstance(expr, tuple) and len(expr) == 3:
            op, left, right = expr
            if op == '&':
                # A & (A | B) = A
                if isinstance(right, tuple) and len(right) == 3 and right[0] == '|':
                    if right[1] == left or right[2] == left:
                        return apply_absorption(left)
                # A & (~A | B) = A & B
                if isinstance(right, tuple) and len(right) == 3 and right[0] == '|':
                    if isinstance(right[1], tuple) and len(right[1]) == 2 and right[1][0] == '~' and right[1][1] == left:
                        return apply_absorption((op, left, right[2]))
                    if isinstance(right[2], tuple) and len(right[2]) == 2 and right[2][0] == '~' and right[2][1] == left:
                        return apply_absorption((op, left, right[1]))
                # A | (A & B) = A
            elif op == '|':
                if isinstance(right, tuple) and len(right) == 3 and right[0] == '&':
                    if right[1] == left or right[2] == left:
                        return apply_absorption(left)
                # A | (~A & B) = A | B
                if isinstance(right, tuple) and len(right) == 3 and right[0] == '&':
                    if isinstance(right[1], tuple) and len(right[1]) == 2 and right[1][0] == '~' and right[1][1] == left:
                        return apply_absorption((op, left, right[2]))
                    if isinstance(right[2], tuple) and len(right[2]) == 2 and right[2][0] == '~' and right[2][1] == left:
                        return apply_absorption((op, left, right[1]))
            # Apply absorption to left operand as well
            new_left = apply_absorption(left)
            new_right = apply_absorption(right)
            if new_left != left or new_right != right:
                return apply_absorption((op, new_left, new_right))
        return expr

    return [apply_absorption(arg) for arg in args]

