def size_to_bytes(size):
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is most of the time rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

    Examples::

        >>> size_to_bytes("500")
        500
        >>> size_to_bytes("1K")
        1000
    """
    if size is None:
        return 0

    size = str(size).strip()
    if not size:
        return 0

    units = {
        'B': 1,
        'K': 1000,
        'M': 1000 ** 2,
        'G': 1000 ** 3,
        'T': 1000 ** 4,
        'P': 1000 ** 5,
        'E': 1000 ** 6,
        'Z': 1000 ** 7,
        'Y': 1000 ** 8,
    }

    size = size.upper()
    for unit in units:
        if size.endswith(unit):
            try:
                value = float(size[:-1])
                return int(value * units[unit])
            except ValueError:
                return 0

    try:
        return int(float(size))
    except ValueError:
        return 0

