            1000
    """
    if size is None:
        return 0

    size = size.strip()
    if not size:
        return 0

    # Define units dictionary with full coverage
    units = {
        'B': 1,
        'K': 1000, 'KB': 1000,
        'M': 1000 ** 2, 'MB': 1000 ** 2,
        'G': 1000 ** 3, 'GB': 1000 ** 3,
        'T': 1000 ** 4, 'TB': 1000 ** 4,
        'P': 1000 ** 5, 'PB': 1000 ** 5,
        'E': 1000 ** 6, 'EB': 1000 ** 6,
        'Z': 1000 ** 7, 'ZB': 1000 ** 7,
        'Y': 1000 ** 8, 'YB': 1000 ** 8,
    }

    # Try to parse with two-character units first (KB, MB, etc.)
    if len(size) >= 2 and size[-2:].upper() in units:
        unit = size[-2:].upper()
        try:
            number = float(size[:-2])
            return int(number * units[unit])
        except ValueError:
            pass

    # Try to parse with one-character units (K, M, G, etc.)
    if len(size) >= 1 and size[-1].upper() in units:
        unit = size[-1].upper()
        try:
            number = float(size[:-1])
            return int(number * units[unit])
        except ValueError:
            pass

    # Fallback: try to parse as plain number
    try:
        return int(float(size))
    except ValueError:
        return 0

