def unquote(name):
    """Remove quote from the given name."""
    if isinstance(name, bytes):
        def unquoted_char(match):
            if len(match.group()) == 1:
                return match.group
            elif match.group()[1] == ord('x'):
                return bytes([int(match.group()[2:], 16)])
            else:
                return bytes([int(match.group()[1:])])
        return re.sub(b";[0-9]{3}", unquoted_char, name, re.S)
    else:
        def unquoted_char(match):
            if len(match.group()) == 1:
                return match.group
            elif match.group()[1] == 'x':
                return chr(int(match.group()[2:], 16))
            else:
                return chr(int(match.group()[1:]))
        return re.sub(";[0-9]{3}", unquoted_char, name, re.S)

