import os
import platform

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    if platform.system() != 'Windows':
        return False
    # Check for gitbash-specific environment variables or conditions
    if 'GIT_BASH' in os.environ:
        return True
    if 'MSYSTEM' in os.environ and os.environ['MSYSTEM'].startswith('MINGW'):
        return True
    # Additional check: look for git.exe in PATH that might indicate gitbash
    try:
        import subprocess
        result = subprocess.run(['where', 'git.exe'], capture_output=True, text=True, shell=True)
        if result.returncode == 0 and 'git' in result.stdout.lower():
            # Check if the path contains gitbash-specific directories
            git_path = result.stdout.strip().split('\n')[0]
            if any(dir_part in git_path.lower() for dir_part in ['mingw', 'git', 'bash']):
                return True
    except Exception:
        pass
    return False

def write_configuration(target_config_filename, rendered_config_yaml, overwrite=False):
    import os
    import yaml

    if os.path.exists(target_config_filename) and not overwrite:
        return

    target_dir = os.path.dirname(target_config_filename)
    if target_dir:
        os.makedirs(target_dir, exist_ok=True)

    with open(target_config_filename, 'w') as config_file:
        config_file.write(rendered_config_yaml)

