def _get_seq_with_type(seq, bufsize=None):
    import lena.core.fill_compute_seq as fill_compute_seq
    import lena.core.fill_request_seq as fill_request_seq
    import lena.core.sequence as sequence
    import lena.core.exceptions as exceptions
    import lena.core.context as ct

    if isinstance(seq, tuple):
        seq = sequence.Sequence(*seq)
    else:
        seq = sequence.Sequence(seq)

    if ct.is_fill_compute_seq(seq):
        seq_type = "fill_compute"
    elif ct.is_fill_request_seq(seq):
        seq_type = "fill_request"
    elif isinstance(seq, sequence.Sequence):
        seq_type = "sequence"
    else:
        raise exceptions.LenaTypeError(
            "unknown argument type. Must be a "
            "FillComputeSeq, FillRequestSeq or Source, "
            "{} provided".format(seq)
        )

    return (seq, seq_type)

